/////////////////////////////////
// cp_vs_sret_spelp
//   In VS-mode, write vsstatus.SPP and vsstatus.SPELP through sstatus and SRET to a non-LPAD instruction
//   in VS-mode or VU-mode, for each value of henvcfg.LPE and senvcfg.LPE.  HS-mode sets sstatus.SPELP to
//   the opposite value first.  Only vsstatus.SPELP = 1 with the LPE of the new mode set raises a
//   software-check exception.  After an SRET to VS-mode, vsstatus.SPELP must read 0.
/////////////////////////////////

  LI(x14, HENVCFG_LPE)
  csrc henvcfg, x14
  LI(x14, SENVCFG_LPE)
  csrc senvcfg, x14
  LI(x14, SSTATUS_SPELP)
  csrs sstatus, x14 # HS-mode SPELP = 1
  RVTEST_TSBI_GOTO_VSMODE
# vsstatus.SPP = VS-mode, vsstatus.SPELP = 0
  LI(x14, SSTATUS_SPP)
  csrs sstatus, x14
  LI(x14, SSTATUS_SPELP)
  csrc sstatus, x14
  LA(x14, ZicfilpH_cg_cp_vs_sret_spelp_to_vs_henvcfg0_senvcfg0_spelp0_target)
  csrw sepc, x14
ZicfilpH_cg_cp_vs_sret_spelp_to_vs_henvcfg0_senvcfg0_spelp0:
  sret
  .p2align 2
ZicfilpH_cg_cp_vs_sret_spelp_to_vs_henvcfg0_senvcfg0_spelp0_target:
  addi x0, x0, 0 # software-check exception only if vsstatus.SPELP = 1 and the new mode's LPE = 1
  lpad 0 # resume point after the software-check exception
# SRET cleared vsstatus.SPELP
  csrr x14, sstatus
  LI(x9, SSTATUS_SPELP)
  and x14, x14, x9
  # Check if x14 contains the expected result. x2 is the signature ptr, x5 is the link ptr, x4 is a temp reg.
  RVTEST_SIGUPD(x2, x5, x4, x14, ZicfilpH_cg_cp_vs_sret_spelp_to_vs_henvcfg0_senvcfg0_spelp0, ZicfilpH_cg_cp_vs_sret_spelp_to_vs_henvcfg0_senvcfg0_spelp0_str)
  RVTEST_TSBI_GOTO_SMODE
  LA(x14, rvtest_trap_count)
  LREG x14, 0(x14)
  # Check if x14 contains the expected result. x2 is the signature ptr, x5 is the link ptr, x4 is a temp reg.
  RVTEST_SIGUPD(x2, x5, x4, x14, ZicfilpH_cg_cp_vs_sret_spelp_to_vs_henvcfg0_senvcfg0_spelp0, ZicfilpH_cg_cp_vs_sret_spelp_to_vs_henvcfg0_senvcfg0_spelp0_str)

  LI(x14, HENVCFG_LPE)
  csrc henvcfg, x14
  LI(x14, SENVCFG_LPE)
